(()=>{let t=0,i=0,s=0;document.addEventListener("scroll",()=>t++,{passive:!0}),document.addEventListener("click",()=>i++,{passive:!0}),document.addEventListener("keydown",()=>s++,{passive:!0});const r=()=>{if(document.visibilityState!=="visible")return!1;const e=document.querySelectorAll("video, audio");for(let n=0;n<e.length;n++){const l=e[n];if(!l.paused&&!l.ended&&l.readyState>2)return!0}return!1};setInterval(()=>{const e=r();if(!(t===0&&i===0&&s===0&&!e)){try{chrome.runtime.sendMessage({type:"ACTIVITY",scrolls:t,clicks:i,keys:s,playing:e,url:location.hostname,visible:document.visibilityState==="visible"})}catch{}t=0,i=0,s=0}},1e4)})();
